"""Magnus 作业提交器 —— TRELLIS.2 on A100（three_d 模型质量线，D15 后）。

用法（token 只走环境变量，绝不落文件）：
  export MAGNUS_TOKEN_ZHU=sk-...
  python3 three_d/tools/magnus/submit.py gen [seed]   # 生成作业（textured GLB）
  python3 three_d/tools/magnus/submit.py logs <job_id> [--all]   # 拉日志（--all 拼全部分页）
  python3 three_d/tools/magnus/submit.py list
  python3 three_d/tools/magnus/submit.py kill <job_id>

平台事实（探针 job 3e3af3c7406696f3 实测，2026-10-04）：
* A100 80GB / CUDA 12.4 / torch 2.6.0+cu124 / nvcc ✓ / Python 3.12
* 容器网络：github.com ✗、github.mgslabs.uk ✓、hf-mirror ✓、tuna pypi ✓、hf.co ✗
* /data 只读 → 产物经日志 base64 回传；repo_name 用用户自己的
  Rise-AGI/landscape-dynamics（勿用他人仓 CNS——用户明示）。
* 依赖策略：pypi(tuna) 装 cumesh/utils3d/xformers/常规件；o-voxel+trellis2 源码
  构建走中转 tarball（含 utils3d@9a4eb15 钉版）；nvdiffrast 不需要（只影响预览
  视频渲染，GLB 导出走 o_voxel.postprocess.to_glb + cumesh）。
"""

from __future__ import annotations

import json
import os
import subprocess
import sys

BASE = "https://zhustation.phybench.cn"
REF_B64 = ""

GEN_TEMPLATE = r"""
set -o pipefail
echo "=== TRELLIS.2 GPU GEN v3 selfclone seed=__SEED__ ==="
export HF_HOME=/tmp/hf HF_ENDPOINT=https://hf-mirror.com HF_HUB_DISABLE_XET=1
export ATTN_BACKEND=xformers PATH=/usr/local/cuda/bin:$PATH
nvidia-smi 2>&1 | head -6 || true
echo "--- clones (internal mirror, 429 退避重试) ---"
mclone() { local url=$1 dest=$2 br=${3:-}; for i in 1 2 3 4 5 6 7 8; do git clone -q ${br:+--branch $br} "$url" "$dest" 2>/dev/null && return 0; echo "mclone retry $i: $url"; sleep 30; done; return 1; }
mclone https://github.mgslabs.uk/microsoft/TRELLIS.2.git /opt/t2 || { echo CLONE_T2_FAIL; exit 1; }
mclone https://github.mgslabs.uk/EasternJournalist/utils3d.git /opt/utils3d || echo CLONE_U3D_FAIL
git -C /opt/utils3d checkout -q 9a4eb15e4021b67b12c460c7057d642626897ec8 || true
mclone https://github.mgslabs.uk/NVlabs/nvdiffrast.git /opt/nvdiffrast v0.4.0 || true
cd /opt/t2
echo "--- eigen (apt / mirror-git / pip 三级回退) ---"
rm -f /tmp/eigen_inc
(apt-get update -qq && apt-get install -y -qq libeigen3-dev zlib1g-dev libjpeg-dev) >/tmp/apt.log 2>&1 || echo APT_FAIL
[ -e /usr/include/eigen3/Eigen/Core ] && ln -sfn /usr/include/eigen3 /tmp/eigen_inc
[ -e /tmp/eigen_inc ] || { ( for i in 1 2 3 4 5; do git clone -q --depth 1 https://github.mgslabs.uk/libeigen/eigen.git /opt/eigen 2>/dev/null && break; sleep 30; done ) && ln -sfn /opt/eigen /tmp/eigen_inc; }
[ -e /tmp/eigen_inc ] || { pip3 install -q eigen 2>/dev/null; P=$(python3 -c "import eigen,os;print(os.path.dirname(eigen.__file__))" 2>/dev/null) && [ -n "$P" ] && ln -sfn "$P" /tmp/eigen_inc; }
mkdir -p o-voxel/third_party
[ -e o-voxel/third_party/eigen ] || ln -sfn /tmp/eigen_inc o-voxel/third_party/eigen
ls o-voxel/third_party/eigen/ 2>/dev/null | head -3 || true
echo EIGEN_RESOLVED
echo "--- pip deps (tuna) ---"
pip3 install -q -i https://pypi.tuna.tsinghua.edu.cn/simple imageio imageio-ffmpeg tqdm easydict opencv-python-headless ninja trimesh pandas kornia timm xformers "transformers>=4.55" pillow accelerate 2>&1 | tail -2 || true
pip3 install -q -i https://pypi.tuna.tsinghua.edu.cn/simple cumesh >/dev/null 2>&1 || true
python3 -c "import cumesh" 2>/dev/null || {
  ( for i in 1 2 3 4 5; do git clone -q --recursive https://github.mgslabs.uk/JeffreyXiang/CuMesh.git /opt/CuMesh 2>/dev/null && break; sleep 30; done ) || echo CUMESH_CLONE_FAIL
  pip3 install --no-build-isolation /opt/CuMesh >/tmp/cumesh.log 2>&1 || { echo CUMESH_BUILD_FAIL; tail -20 /tmp/cumesh.log; }
}
python3 -c "import cumesh; print('cumesh OK')" || echo CUMESH_STILL_FAIL
echo "--- flex_gemm (hard dep, v5 实测) ---"
mclone https://github.mgslabs.uk/JeffreyXiang/FlexGEMM.git /opt/FlexGEMM || echo FLEXGEMM_CLONE_FAIL
[ -d /opt/FlexGEMM ] && pip3 install --no-build-isolation /opt/FlexGEMM >/tmp/bfg.log 2>&1 || { echo FLEXGEMM_BUILD_FAIL; tail -20 /tmp/bfg.log; } || true
python3 -c "import flex_gemm; print('flex_gemm OK')" || echo FLEXGEMM_STILL_FAIL
echo "--- build from source ---"
pip3 install --no-build-isolation -q /opt/utils3d >/tmp/b1.log 2>&1 || { echo U3D_FAIL; tail -15 /tmp/b1.log; } || true
pip3 install --no-build-isolation -e /opt/t2/o-voxel >/tmp/b2.log 2>&1 || { echo OVOXEL_FAIL; tail -25 /tmp/b2.log; } || true
pip3 install --no-build-isolation -e /opt/t2 >/tmp/b3.log 2>&1 || { echo T2_FAIL; tail -25 /tmp/b3.log; } || true
echo BUILDS_ATTEMPTED
[ -d /opt/nvdiffrast ] && pip3 install --no-build-isolation -q /opt/nvdiffrast 2>&1 | tail -2 || true
python3 -c "import o_voxel, trellis2; print('imports OK')" || echo IMPORTS_FAIL
echo "--- dinov3 -> camenduru ---"
grep -rl "facebook/dinov3-vitl16-pretrain-lvd1689m" configs/ | xargs -r sed -i "s|facebook/dinov3-vitl16-pretrain-lvd1689m|camenduru/dinov3-vitl16-pretrain-lvd1689m|g"
grep -l camenduru configs/gen/*.json | wc -l
echo "--- weights ---"
python3 - <<'WEOF'
import os
os.environ["HF_ENDPOINT"]="https://hf-mirror.com"; os.environ["HF_HUB_DISABLE_XET"]="1"
from huggingface_hub import snapshot_download
for repo in ["microsoft/TRELLIS.2-4B","camenduru/dinov3-vitl16-pretrain-lvd1689m","ZhengPeng7/BiRefNet"]:
    snapshot_download(repo_id=repo); print("CACHED", repo)
WEOF
echo "--- ref image (embedded) ---"
echo __REFB64__ | base64 -d > /tmp/ref.png && ls -la /tmp/ref.png
echo "--- run ---"
python3 - <<'REOF' 2>&1 | tail -25
import os, time
os.environ["ATTN_BACKEND"]="xformers"
from trellis2.pipelines import Trellis2ImageTo3DPipeline
import o_voxel
from PIL import Image
t0=time.time()
pipe=Trellis2ImageTo3DPipeline.from_pretrained("microsoft/TRELLIS.2-4B"); pipe.cuda()
img=Image.open("/tmp/ref.png").convert("RGB")
mesh=pipe.run(img, seed=__SEED__)[0]
print("GEN_OK", round(time.time()-t0,1))
t1=time.time()
glb=o_voxel.postprocess.to_glb(vertices=mesh.vertices, faces=mesh.faces,
    attr_volume=mesh.attrs, coords=mesh.coords, attr_layout=mesh.layout,
    voxel_size=mesh.voxel_size, aabb=[[-0.5,-0.5,-0.5],[0.5,0.5,0.5]],
    decimation_target=200000, texture_size=1024,
    remesh=True, remesh_band=1, remesh_project=0, verbose=True)
print("TOGLB_OK", round(time.time()-t1,1))
glb.export("/tmp/out.glb"); print("GLB_SAVED")
REOF
ls -la /tmp/out.glb || { echo NO_GLB; exit 2; }
python3 - <<'BEOF'
import base64
data=open("/tmp/out.glb","rb").read()
print("GLB_BYTES", len(data))
b64=base64.b64encode(data).decode(); CH=800000
n=(len(b64)+CH-1)//CH
print("GLB_B64_BEGIN", n)
for i in range(n):
    print("CHUNK", i, b64[i*CH:(i+1)*CH])
print("GLB_B64_END")
BEOF
echo "GENDONE seed=__SEED__"
""".replace("__REFB64__", "__REF_B64__")


def gen_entry(seed: int) -> str:
    return GEN_TEMPLATE.replace("__SEED__", str(seed)).replace("__REF_B64__", REF_B64)


def _curl(method: str, path: str, payload: dict | None = None) -> str:
    token = os.environ.get("MAGNUS_TOKEN_ZHU")
    if not token:
        sys.exit("缺 MAGNUS_TOKEN_ZHU（环境变量）")
    cmd = ["curl", "-s", "-m", "60", "-A", "curl/8.7.1",
           "-H", f"Authorization: Bearer {token}", f"{BASE}{path}"]
    if payload is not None:
        cmd += ["-H", "Content-Type: application/json",
                "-X", method, "-d", json.dumps(payload)]
    r = subprocess.run(cmd, capture_output=True, text=True)
    return r.stdout


def submit(task_name: str, entry: str) -> str:
    payload = {
        "task_name": task_name,
        "entry_command": entry,
        # 用户自己的仓（勿用他人 CNS）；此 sha=昨日成功作业同款
        "repo_name": "landscape-dynamics",
        "branch": "halluscope",  # OU 仓默认分支（main 不存在，实测两次翻车）
        "commit_sha": "5b1f616c7f436e0da6ff4f8ad721fc8720ad22ae",
        "namespace": "Rise-AGI",
        "container_image": "docker://vllm/vllm-openai:v0.8.5",
        "gpu_type": "a100",
        "gpu_count": 1,
        "job_type": "A2",
        "cpu_count": 16,
        "memory_demand": "64G",
        "ephemeral_storage": "96G",
        "system_entry_command": 'export APPTAINER_BIND="/data/zhouzihan:/data/zhouzihan"',
        "description": task_name,
    }
    return _curl("POST", "/api/jobs/submit", payload)


def get_logs(job_id: str, all_pages: bool = False) -> str:
    out, page = [], 0
    while True:
        raw = _curl("GET", f"/api/jobs/{job_id}/logs?page={page}")
        try:
            d = json.loads(raw)
        except ValueError:
            return raw
        out.append(d.get("logs") or "")
        total = int(d.get("total_pages") or 1)
        page += 1
        if not all_pages or page >= total:
            break
    return "".join(out)


def main() -> None:
    mode = sys.argv[1] if len(sys.argv) > 1 else "list"
    if mode == "gen":
        seed = int(sys.argv[2]) if len(sys.argv) > 2 else 42
        raw = submit(f"trellis2pet-gen-s{seed}", gen_entry(seed))
        try:
            print("submitted:", json.loads(raw)["id"])
        except ValueError:
            print(raw[:400])
    elif mode == "logs":
        tail = get_logs(sys.argv[2], all_pages="--all" in sys.argv)
        print(tail if "--all" in sys.argv else tail[-4000:])
    elif mode == "kill":
        print(_curl("POST", f"/api/jobs/{sys.argv[2]}/terminate", {}))
    elif mode == "list":
        print(_curl("GET", "/api/jobs?page=0&page_size=10")[:1500])
    else:
        print(__doc__)


if __name__ == "__main__":
    main()
